-- YMCA Prime Training: aggiornamento del database alla versione 1.2
-- Chi ha già eseguito la 1.1 lo incolla nel SQL Editor di Supabase ed esegue UNA volta sola.
-- Chi parte da zero non deve farlo: setup.sql contiene già tutto (questo file è in fondo, identico).
--
-- Novità: archivio esercizi ampliato (oltre 640 esercizi), video degli esercizi registrati dal telefono del PT
-- (contenitore «exercise-videos») e «Classifica delle tonnellate»: chi ha sollevato di più, a partecipazione facoltativa.

-- ───────── Video degli esercizi ─────────
-- Il PT registra (o sceglie) un video dal telefono: finisce nel contenitore pubblico «exercise-videos» (massimo 50 MB,
-- mp4, mov o webm) e il suo indirizzo si salva in exercises.video_url, come un link. Li scrive solo lo staff.
-- Se il progetto ha un limite di dimensione globale più basso (Storage > Settings), vale quello.
do $$
begin
  if to_regclass('storage.buckets') is null then return; end if;
  on conflict (id) do update set file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;
  if not exists (select 1 from pg_policies where schemaname = 'storage' and tablename = 'objects' and policyname = 'video esercizi: lo staff li gestisce') then
    execute $p$create policy "video esercizi: lo staff li gestisce" on storage.objects for all
      using (bucket_id = 'exercise-videos' and public.is_staff()) with check (bucket_id = 'exercise-videos' and public.is_staff())$p$;
  end if;
end $$;

-- ───────── Nuovi esercizi ─────────
-- Gli esercizi che esistono già (stesso nome) non vengono toccati.

-- <seed-esercizi-1-2>
-- (generato da scripts/gen-seed-sql.cjs: 646 esercizi in tutto, 364 nuovi)
on conflict do nothing;
-- </seed-esercizi-1-2>

-- ───────── Classifica delle tonnellate ─────────
-- Ogni socio decide se comparire: di default no. Chi partecipa mostra agli altri solo nome e iniziale del cognome
-- (es. «Marco R.») e le tonnellate; mai schede, pesi dei singoli esercizi o altri dati.

alter table profiles add column if not exists leaderboard_opt_in boolean not null default false;

create or replace function set_leaderboard(p_on boolean) returns boolean
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then raise exception 'login_required'; end if;
  update profiles set leaderboard_opt_in = coalesce(p_on, false) where id = auth.uid() and role = 'member';
  if not found then raise exception 'only_members'; end if;
  return coalesce(p_on, false);
end $$;

-- Tonnellate = somma di (peso × ripetizioni) delle serie registrate con un carico. Gli esercizi a corpo libero senza zavorra valgono zero.
-- p_period: week | month | year | all (periodi calcolati sull'ora di Roma). Restituisce i primi 50 partecipanti.
create or replace function leaderboard(p_period text default 'all') returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_me uuid := auth.uid();
  v_staff boolean := is_staff();
  v_since timestamptz;
  v jsonb;
begin
  if v_me is null then raise exception 'login_required'; end if;
  if p_period is null or p_period not in ('week', 'month', 'year', 'all') then raise exception 'invalid_period'; end if;
  v_since := case p_period
    when 'week' then date_trunc('week', now() at time zone 'Europe/Rome') at time zone 'Europe/Rome'
    when 'month' then date_trunc('month', now() at time zone 'Europe/Rome') at time zone 'Europe/Rome'
    when 'year' then date_trunc('year', now() at time zone 'Europe/Rome') at time zone 'Europe/Rome'
    else null end;

  with t as (
    select s.member_id, sum(s.weight_kg * s.reps) as kg, count(*) as sets, count(distinct s.workout_id) as workouts
    from set_logs s join workouts w on w.id = s.workout_id
    where s.weight_kg > 0 and s.reps > 0 and (v_since is null or w.started_at >= v_since)
    group by s.member_id
  ), r as (
    select p.id, t.kg, t.sets, t.workouts,
           rank() over (order by t.kg desc) as pos,
           case when v_staff then p.full_name
                else coalesce(nullif(btrim(coalesce(p.first_name, '') || ' ' || coalesce(left(btrim(p.last_name), 1) || '.', '')), ''), 'Socio') end as shown
    from profiles p join t on t.member_id = p.id
    where p.role = 'member' and p.active and p.leaderboard_opt_in
  )
  select jsonb_build_object(
    'period', p_period,
    'since', v_since,
    'participants', (select count(*) from profiles where role = 'member' and active and leaderboard_opt_in),
    'ranked', (select count(*) from r),
    'total_kg', (select coalesce(sum(kg), 0) from r),
    'me', jsonb_build_object(
      'opt_in', coalesce((select leaderboard_opt_in from profiles where id = v_me), false),
      'rank', (select pos from r where id = v_me),
      'kg', coalesce((select kg from t where member_id = v_me), 0),
      'sets', coalesce((select sets from t where member_id = v_me), 0),
      'workouts', coalesce((select workouts from t where member_id = v_me), 0),
      'kg_all', coalesce((select sum(s.weight_kg * s.reps) from set_logs s where s.member_id = v_me and s.weight_kg > 0 and s.reps > 0), 0)),
    'rows', coalesce((select jsonb_agg(jsonb_build_object(
        'rank', x.pos, 'name', x.shown, 'kg', x.kg, 'sets', x.sets, 'workouts', x.workouts, 'is_me', x.id = v_me,
        'id', case when v_staff or x.id = v_me then x.id end) order by x.pos, x.shown)
      from (select * from r order by pos, shown limit 50) x), '[]'::jsonb)
  ) into v;
  return v;
end $$;
